1	/**
2	 * 全量一轮：插件全部能力，不依赖 Chrome 扩展
3	 *
4	 *  1) 赛狐 OpenAPI → 下架点名（selectStatus 离开 12）
5	 *  2) Playwright  → 多店会话切店 + 待关注/近期下降点名 + 在售数字
6	 *  3) 飞书汇总
7	 */
8	import { existsSync } from 'node:fs';
9	import { resolve } from 'node:path';
10	import { launchBrowser, isLoggedIn } from './browser.js';
11	import { closePopups } from './popups.js';
12	import { scanStore } from './monitor.js';
13	import { loadState, saveState, diffStore, mergeSnapshot } from './state.js';
14	import { sendFeishu } from './feishu.js';
15	import { switchSessionStore, readCurrentStoreName } from './sessionStores.js';
16	import { loadSellfoxConfig, sellfoxConfigReady } from './sellfox/config.js';
17	import { runSellfoxOnce } from './sellfox/monitor.js';
18	import { ROOT } from './config.js';
19	import { log } from './logger.js';
20	
21	function resolveStoreList(cfg) {
22	  // 优先 config.storeList；否则用赛狐配置店名
23	  if (Array.isArray(cfg.storeList) && cfg.storeList.length) {
24	    return cfg.storeList.map(String);
25	  }
26	  try {
27	    const sf = loadSellfoxConfig();
28	    const names = (sf.stores || [])
29	      .filter((s) => s.enabled !== false)
30	      .map((s) => s.name)
31	      .filter(Boolean);
32	    if (names.length) return names;
33	  } catch {
34	    /* ignore */
35	  }
36	  return [];
37	}
38	
39	function sellfoxAvailable() {
40	  const p = resolve(ROOT, 'sellfox.config.json');
41	  if (!existsSync(p) && !process.env.SELLFOX_CLIENT_ID) return false;
42	  try {
43	    const c = loadSellfoxConfig();
44	    return sellfoxConfigReady(c).ok;
45	  } catch {
46	    return false;
47	  }
48	}
49	
50	/**
51	 * @param {object} cfg loadConfig()
52	 * @param {{ skipSellfox?: boolean, skipBrowser?: boolean, dryRun?: boolean }} [opts]
53	 */
54	export async function runFullOnce(cfg, opts = {}) {
55	  const report = {
56	    sellfox: null,
57	    browser: null,
58	    events: [],
59	  };
60	  const allLines = [];
61	
62	  // ---------- 1) 赛狐下架 ----------
63	  if (!opts.skipSellfox && sellfoxAvailable() && cfg.alerts?.delist !== false) {
64	    try {
65	      log.info('=== [1/2] 赛狐下架监测 ===');
66	      const sfCfg = loadSellfoxConfig();
67	      // 飞书：dry 时不发；正式时 sellfox 模块自己发，避免 double——这里 dryRun 控制
68	      const r = await runSellfoxOnce(sfCfg, { dryRun: !!opts.dryRun });
69	      report.sellfox = r;
70	      // 已在 runSellfoxOnce 内发飞书；汇总记一条
71	      for (const s of r.summary || []) {
72	        if (s.events?.includes('delist')) {
73	          report.events.push({ store: s.store, type: 'delist', via: 'sellfox' });
74	        }
75	      }
76	    } catch (e) {
77	      log.error('赛狐下架失败：', e.message);
78	      report.sellfox = { error: e.message };
79	      if (!opts.dryRun) {
80	        await sendFeishu(cfg, {
81	          title: '⚠️ 赛狐下架监测失败',
82	          template: 'orange',
83	          lines: [String(e.message), `_时间：${new Date().toLocaleString('zh-CN')}_`],
84	        }).catch(() => {});
85	      }
86	    }
87	  } else {
88	    log.info('跳过赛狐下架（未配置或 skipSellfox）');
89	  }
90	
91	  // ---------- 2) 浏览器：流量 + 在售数字 ----------
92	  if (opts.skipBrowser) {
93	    log.info('跳过浏览器扫描');
94	    return report;
95	  }
96	
97	  log.info('=== [2/2] 浏览器流量/在售监测 ===');
98	  const { context, page } = await launchBrowser(cfg);
99	  try {
100	    if (!(await isLoggedIn(page, cfg))) {
101	      const err = new Error('未登录。请先运行 `npm run login`。');
102	      err.code = 'NOT_LOGGED_IN';
103	      throw err;
104	    }
105	    await closePopups(page);
106	
107	    let stores = resolveStoreList(cfg);
108	    if (!stores.length) {
109	      const cur = await readCurrentStoreName(page);
110	      stores = [cur || '(当前店铺)'];
111	      log.info('未配置 storeList，监测当前店：', stores[0]);
112	    } else {
113	      log.info('店铺清单：', stores.join(', '));
114	    }
115	
116	    const state = loadState();
117	    state.stores = state.stores || {};
