23	/** 是否视为「在售/上架可售」——用于下架 diff 的当前集合 */
24	export function isActiveGoods(g) {
25	  // retrieve 接口可能直接返回 goodsStatus 字符串
26	  const gs = String(g?.goodsStatus || g?.goods_status || '').toUpperCase();
27	  if (gs === 'ACTIVE' || gs === 'ON_SALE' || gs === 'ONSALE') return true;
