42	
43	export function isLowTraffic(g) {
44	  const t = Number(g?.lowTrafficTag);
45	  if (t === 1) return true;
46	  if (t === 2) return false;
47	  return false;
48	}
49	
50	export function isRestrictedTraffic(g) {
51	  const t = Number(g?.restrictedTrafficTag);
52	  if (t === 1) return true;
53	  if (t === 2) return false;
54	  return false;
55	}
56	
57	export function normalizeGoods(g, { assumedActive = false } = {}) {
58	  const id = goodsIdOf(g);
59	  if (!id) return null;
60	  const row = assumedActive ? { ...g, __assumedActive: true } : g;
61	  return {
62	    goodsId: id,
63	    name: nameOf(g),
64	    active: isActiveGoods(row),
65	    lowTraffic: isLowTraffic(g),
66	    restrictedTraffic: isRestrictedTraffic(g),
67	    status4VO: g?.status4VO ?? null,
68	    subStatus4VO: g?.subStatus4VO ?? null,
69	    goodsShowSubStatus: g?.goodsShowSubStatus ?? null,
70	    goodsStatus: g?.goodsStatus ?? null,
71	    outGoodsSn: g?.outGoodsSn || '',
72	    thumbUrl: g?.thumbUrl || '',
73	  };
74	}
75	
76	/**
77	 * 分页拉全量（list.query）
78	 * goodsSearchType: 1=Available/off the shelf, 4=unpublished, 5=draft, 6=deleted
79	 */
80	export async function fetchAllListQuery(client, accessToken, {
81	  goodsSearchType = 1,
82	  goodsStatusFilterType,
83	  goodsSearchTags,
84	  pageSize = PAGE_SIZE_MAX,
85	  assumedActive = false,
86	} = {}) {
87	  const size = Math.min(PAGE_SIZE_MAX, Math.max(1, Number(pageSize) || PAGE_SIZE_MAX));
88	  const all = [];
89	  let pageNo = 1;
90	  let total = null;
91	  for (;;) {
92	    const biz = {
93	      pageNo,
94	      pageSize: size,
95	      goodsSearchType,
96	    };
97	    if (goodsStatusFilterType != null) biz.goodsStatusFilterType = goodsStatusFilterType;
98	    if (Array.isArray(goodsSearchTags) && goodsSearchTags.length) biz.goodsSearchTags = goodsSearchTags;
99	
100	    const data = await client.call('bg.local.goods.list.query', biz, { accessToken });
101	    const result = data.result || {};
102	    const list = result.goodsList || result.data || [];
103	    if (typeof result.total === 'number') total = result.total;
104	    for (const g of list) {
105	      const n = normalizeGoods(g, { assumedActive });
106	      if (n) all.push(n);
107	    }
108	    if (!list.length) break;
109	    if (total != null && all.length >= total) break;
110	    if (list.length < size) break;
111	    pageNo += 1;
112	    if (pageNo > 500) throw new Error('list.query 分页超过 500 页，中止防死循环');
113	  }
114	  return { items: all, total: total ?? all.length };
115	}
116	
117	/**
118	 * 分页拉全量（list.retrieve）
119	 * goodsSearchType: ALL | ACTIVE | INACTIVE | INCOMPLETE | DRAFT | DELETED
120	 */
121	export async function fetchAllListRetrieve(client, accessToken, {
122	  goodsSearchType = 'ACTIVE',
123	  goodsSearchTags,
124	  pageSize = PAGE_SIZE_MAX,
125	} = {}) {
126	  const size = Math.min(PAGE_SIZE_MAX, Math.max(1, Number(pageSize) || PAGE_SIZE_MAX));
127	  const all = [];
128	  let pageToken = undefined;
129	  let total = null;
130	  let guard = 0;
131	  const assumedActive = String(goodsSearchType).toUpperCase() === 'ACTIVE';
132	  for (;;) {
133	    const biz = {
134	      goodsSearchType,
135	      pageSize: size,
136	    };
137	    if (pageToken) biz.pageToken = pageToken;
138	    if (Array.isArray(goodsSearchTags) && goodsSearchTags.length) biz.goodsSearchTags = goodsSearchTags;
139	
140	    const data = await client.call('temu.local.goods.list.retrieve', biz, { accessToken });
141	    const result = data.result || {};
142	    const list = result.goodsList || result.data || [];
143	    if (typeof result.total === 'number') total = result.total;
144	    for (const g of list) {
145	      const n = normalizeGoods(g, { assumedActive });
146	      if (n) all.push(n);
147	    }
148	    const next = result.pagination?.nextToken || result.nextToken || null;
149	    if (!list.length || !next) break;
150	    pageToken = next;
151	    guard += 1;
152	    if (guard > 500) throw new Error('list.retrieve 分页超过 500 页，中止防死循环');
153	  }
154	  return { items: all, total: total ?? all.length };
155	}
156	
157	/**
158	 * 拉一店完整监测快照所需数据：
159	 *  - 在售集合（ACTIVE）
160	 *  - 低流量集合（tag=1）
161	 *  - 限流集合（tag=4）
162	 */
163	export async function fetchStoreCatalog(client, accessToken, cfg = {}) {
164	  const mode = cfg.apiMode === 'listRetrieve' ? 'listRetrieve' : 'listQuery';
165	  const pageSize = cfg.pageSize || PAGE_SIZE_MAX;
166	
167	  let activeItems;
168	  if (mode === 'listRetrieve') {
169	    ({ items: activeItems } = await fetchAllListRetrieve(client, accessToken, {
170	      goodsSearchType: 'ACTIVE',
171	      pageSize,
172	    }));
173	  } else {
174	    // list.query：用 type=1 拉「可售/下架」合集，再按 isActiveGoods 过滤
175	    // 若 status 字段识别不准，可在 openapi.config 设 forceAssumeActiveOnType1: true
176	    const force = cfg.forceAssumeActiveOnType1 === true;
177	    const { items } = await fetchAllListQuery(client, accessToken, {
178	      goodsSearchType: 1,
179	      goodsStatusFilterType: 1,
180	      pageSize,
181	      assumedActive: force,
182	    });
183	    activeItems = force ? items : items.filter((x) => x.active);
184	    // 若过滤后为空但原列表非空，降级：整表当作候选在售并打日志（避免误判全下架）
185	    if (!activeItems.length && items.length) {
186	      activeItems = items.map((x) => ({ ...x, active: true }));
187	    }
188	  }
189	
190	  // 流量标签：优先用 goodsSearchTags 直接筛（更准、更省）
191	  let lowItems = [];
192	  let restrictedItems = [];
193	  try {
194	    if (mode === 'listRetrieve') {
195	      ({ items: lowItems } = await fetchAllListRetrieve(client, accessToken, {
196	        goodsSearchType: 'ALL',
197	        goodsSearchTags: [1],
198	        pageSize,
199	      }));
200	      ({ items: restrictedItems } = await fetchAllListRetrieve(client, accessToken, {
201	        goodsSearchType: 'ALL',
202	        goodsSearchTags: [4],
203	        pageSize,
204	      }));
205	    } else {
206	      ({ items: lowItems } = await fetchAllListQuery(client, accessToken, {
207	        goodsSearchType: 1,
208	        goodsSearchTags: [1],
209	        pageSize,
210	        assumedActive: true,
211	      }));
212	      ({ items: restrictedItems } = await fetchAllListQuery(client, accessToken, {
213	        goodsSearchType: 1,
214	        goodsSearchTags: [4],
215	        pageSize,
216	        assumedActive: true,
217	      }));
218	    }
219	  } catch (e) {
220	    // 标签筛选失败时回退：用 ACTIVE 列表上的 tag 字段
221	    lowItems = activeItems.filter((x) => x.lowTraffic);
222	    restrictedItems = activeItems.filter((x) => x.restrictedTraffic);
223	    e._fallback = true;
224	    throw Object.assign(e, { partial: { activeItems, lowItems, restrictedItems } });
225	  }
226	
227	  // 若 tag 筛选返回空，再用字段扫 ACTIVE（兼容「筛选无效但字段有值」）
228	  if (!lowItems.length) lowItems = activeItems.filter((x) => x.lowTraffic);
229	  if (!restrictedItems.length) restrictedItems = activeItems.filter((x) => x.restrictedTraffic);
230	
231	  const toMap = (arr) => {
232	    const m = {};
233	    for (const it of arr) {
234	      if (!it?.goodsId) continue;
235	      m[it.goodsId] = {
236	        name: it.name || '',
237	        lowTraffic: !!it.lowTraffic,
238	        restrictedTraffic: !!it.restrictedTraffic,
239	      };
240	    }
241	    return m;
242	  };
243	
244	  return {
245	    activeMap: toMap(activeItems),
246	    lowTrafficMap: toMap(lowItems.map((x) => ({ ...x, lowTraffic: true }))),
247	    restrictedMap: toMap(restrictedItems.map((x) => ({ ...x, restrictedTraffic: true }))),
248	    counts: {
249	      active: activeItems.length,
250	      lowTraffic: lowItems.length,
251	      restricted: restrictedItems.length,
252	    },
253	    rawSample: activeItems.slice(0, 3),
254	  };
255	}
