1	/**
2	 * 赛狐 Temu 在售集合 diff → 下架
3	 * 在售定义：selectStatus === "12"（已加入站点）
4	 */
5	import { SELECT_STATUS } from './products.js';
6	
7	/**
8	 * @param {object|null} prevSnap { onSaleMap, statusCounts, ts }
9	 * @param {{ onSaleMap: object, statusCounts?: object }} curr
10	 */
11	export function diffOnSale(prevSnap, curr) {
12	  const prevMap = (prevSnap && prevSnap.onSaleMap) || null;
13	  const currMap = curr.onSaleMap || {};
14	  const currIds = Object.keys(currMap);
15	  const events = [];
16	  let skipUpdate = false;
17	
18	  if (prevMap) {
19	    const prevN = Object.keys(prevMap).length;
20	    const currN = currIds.length;
21	    // 防残缺：在售骤降过半且基准≥5 → 跳过（接口窗口漏数）
22	    if (prevN >= 5 && currN < Math.floor(prevN * 0.5)) {
23	      skipUpdate = true;
24	      events.push({
25	        type: 'scan_incomplete',
26	        severity: 'warn',
27	        message: `在售疑似不全：基准 ${prevN} → 本轮 ${currN}，跳过下架判定`,
28	      });
29	    }
30	  }
31	
32	  let delisted = [];
33	  if (prevMap && !skipUpdate) {
34	    delisted = Object.keys(prevMap).filter((id) => !(id in currMap));
35	    if (delisted.length) {
36	      events.push({
37	        type: 'delist',
38	        severity: 'alert',
39	        items: delisted.map((id) => ({
40	          skcId: id,
41	          parentId: prevMap[id]?.parentId || '',
42	          name: prevMap[id]?.name || '',
43	          prevStatus: prevMap[id]?.selectStatus || SELECT_STATUS.ON_SALE,
44	        })),
45	        from: Object.keys(prevMap).length,
46	        to: currIds.length,
47	      });
48	    }
49	  }
50	
51	  const isFirst = !prevMap;
52	  const nextSnap = {
53	    onSaleMap: skipUpdate && prevMap ? prevMap : currMap,
54	    statusCounts: curr.statusCounts || {},
55	    onSaleCount: skipUpdate && prevMap ? Object.keys(prevMap).length : currIds.length,
56	    ts: Date.now(),
57	  };
58	
59	  return { events, nextSnap, isFirst, skipUpdate, delistedCount: delisted.length };
60	}
61	
62	export function editLink(editBaseUrl, parentIdOrProductId) {
63	  const base = String(editBaseUrl || 'https://agentseller.temu.com').replace(/\/$/, '');
64	  // 后台编辑页参数多为 productId；赛狐 parentId 实测常等于商品父 ID，可点
65	  return `${base}/goods/edit?from=productList&productId=${parentIdOrProductId}`;
66	}
67	
68	export function formatDelistLines(storeName, events, { editBaseUrl } = {}) {
69	  const lines = [`**🏬 ${storeName}**（赛狐 OpenAPI）`];
70	  for (const ev of events) {
71	    if (ev.severity !== 'alert' || ev.type !== 'delist') continue;
72	    lines.push(`📉 在售商品下架 ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}，selectStatus 离开 12）：`);
73	    for (const it of ev.items.slice(0, 40)) {
74	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 36);
75	      const pid = it.parentId || it.skcId;
76	      lines.push(`• [${nm}](${editLink(editBaseUrl, pid)})  SKC ${it.skcId || '-'}`);
77	    }
78	    if (ev.items.length > 40) lines.push(`_…另有 ${ev.items.length - 40} 个未列出_`);
79	  }
80	  lines.push('', `_检查时间：${new Date().toLocaleString('zh-CN')}_`);
81	  return lines;
82	}
