1	import crypto from 'node:crypto';
2	import { log } from './logger.js';
3	
4	/**
5	 * 飞书自定义机器人告警。
6	 * 支持可选签名校验（config.feishuSecret）。
7	 */
8	
9	function sign(secret, timestamp) {
10	  const stringToSign = `${timestamp}\n${secret}`;
11	  const hmac = crypto.createHmac('sha256', stringToSign);
12	  hmac.update('');
13	  return hmac.digest('base64');
14	}
15	
16	/**
17	 * 发送一条飞书卡片消息。
18	 * @param {object} cfg
19	 * @param {{title:string, template?:string, lines:string[]}} msg
20	 */
21	export async function sendFeishu(cfg, { title, template = 'red', lines }) {
22	  const hooks = cfg.feishuWebhooks && cfg.feishuWebhooks.length
23	    ? cfg.feishuWebhooks
24	    : (cfg.feishuWebhook ? [cfg.feishuWebhook] : []);
25	  if (!hooks.length) {
26	    log.warn('未配置 feishuWebhooks，跳过告警。内容：', title, lines);
27	    return false;
28	  }
29	  const timestamp = Math.floor(Date.now() / 1000);
30	  const body = {
31	    msg_type: 'interactive',
32	    card: {
33	      config: { wide_screen_mode: true },
34	      header: {
35	        title: { tag: 'plain_text', content: title },
36	        template,
37	      },
38	      elements: [
39	        {
40	          tag: 'div',
41	          text: { tag: 'lark_md', content: lines.join('\n') },
42	        },
43	      ],
44	    },
45	  };
46	  if (cfg.feishuSecret) {
47	    body.timestamp = String(timestamp);
48	    body.sign = sign(cfg.feishuSecret, timestamp);
49	  }
50	
51	  // 依次发往每个群 webhook；任一成功即视为发送成功，互不影响
52	  let anyOk = false;
53	  for (const url of hooks) {
54	    try {
55	      const resp = await fetch(url, {
56	        method: 'POST',
57	        headers: { 'Content-Type': 'application/json' },
58	        body: JSON.stringify(body),
59	      });
60	      const data = await resp.json().catch(() => ({}));
61	      if (data.code && data.code !== 0) {
62	        log.error(`飞书返回错误(...${url.slice(-8)})：`, data);
63	        continue;
64	      }
65	      log.info(`飞书告警已发送(...${url.slice(-8)})：`, title);
66	      anyOk = true;
67	    } catch (e) {
68	      log.error(`飞书发送失败(...${url.slice(-8)})：`, e.message);
69	    }
70	  }
71	  return anyOk;
72	}
