/**
 * 兼容入口：默认跑「全量一轮」（赛狐下架 + 浏览器流量，对齐插件能力）
 * 仅浏览器旧逻辑：FULL_RUN=0 或 cfg.fullRun === false
 */
import { runFullOnce } from './fullRun.js';
import { launchBrowser, isLoggedIn } from './browser.js';
import { listStores, switchStore } from './stores.js';
import { scanStore } from './monitor.js';
import { closePopups } from './popups.js';
import { loadState, saveState, diffStore, mergeSnapshot } from './state.js';
import { sendFeishu } from './feishu.js';
import { log } from './logger.js';

export async function runOnce(cfg) {
  const useFull =
    process.env.FULL_RUN !== '0' &&
    process.env.FULL_RUN !== 'false' &&
    cfg.fullRun !== false;

  if (useFull) {
    log.info('全量监测（赛狐下架 + 浏览器流量，无需插件）');
    return runFullOnce(cfg);
  }

  log.info('仅浏览器监测（FULL_RUN=0）');
  return runBrowserOnly(cfg);
}

/** 旧版：只跑 Playwright，不调用赛狐 */
export async function runBrowserOnly(cfg) {
  const { context, page } = await launchBrowser(cfg);
  try {
    if (!(await isLoggedIn(page, cfg))) {
      const err = new Error('未登录。请先运行 `npm run login` 完成一次人工登录。');
      err.code = 'NOT_LOGGED_IN';
      throw err;
    }
    await closePopups(page);

    const storeNames =
      cfg.stores === 'all' && cfg.storeList.length === 0
        ? await listStores(page)
        : cfg.storeList;
    const singleStore = !storeNames || storeNames.length <= 1;
    const stores = singleStore ? [(storeNames && storeNames[0]) || null] : storeNames;
    if (singleStore) {
      log.info('按单店铺监测聚合视图，店铺：', (storeNames && storeNames[0]) || '(当前)');
    }

    const state = loadState();
    state.stores = state.stores || {};
    const allEvents = [];
    const summaries = [];

    for (const store of stores) {
      const label = store || '(当前店铺)';
      try {
        if (store && !singleStore) {
          const ok = await switchStore(page, store, cfg);
          if (!ok) {
            log.warn(`切换到「${store}」失败，跳过`);
            continue;
          }
        }
        const prev = state.stores[label];
        const result = await scanStore(page, label, cfg, {
          prevWatch: prev?.trafficWatchCount,
        });
        log.info('扫描结果：', result);
        summaries.push(result);
        const events = diffStore(prev, result, cfg.alerts);
        for (const ev of events) allEvents.push({ store: label, ...ev });
        state.stores[label] = mergeSnapshot(prev, result);
      } catch (e) {
        log.error(`店铺「${label}」监测出错：`, e.message);
      }
    }

    saveState(state);

    if (allEvents.length > 0) {
      const lines = [];
      const byStore = {};
      for (const ev of allEvents) (byStore[ev.store] ||= []).push(ev);
      for (const [store, evs] of Object.entries(byStore)) {
        lines.push(`**🏬 ${store}**`);
        for (const ev of evs) {
          const icon = ev.type === 'onSaleDrop' ? '📉' : '⚠️';
          lines.push(`${icon} ${ev.text}`);
        }
        lines.push('');
      }
      lines.push(`_扫描时间：${new Date().toLocaleString('zh-CN')}_`);
      await sendFeishu(cfg, {
        title: '🔔 Temu 店铺监测告警',
        template: 'red',
        lines,
      });
    } else {
      log.info('本轮无异常，未发送告警。');
    }

    return { summaries, events: allEvents };
  } finally {
    await context.close().catch(() => {});
  }
}

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const ROOT = resolve(__dirname, '..');

/** 读取并规范化 config.json */
export function loadConfig() {
  const raw = JSON.parse(readFileSync(resolve(ROOT, 'config.json'), 'utf8'));
  return {
    // 告警目标群 webhook：支持单个字符串或数组（多个群同发）。兼容旧字段 feishuWebhook。
    feishuWebhooks: (Array.isArray(raw.feishuWebhooks)
      ? raw.feishuWebhooks
      : [raw.feishuWebhooks ?? raw.feishuWebhook ?? ''])
      .map((s) => String(s || '').trim()).filter(Boolean),
    feishuSecret: raw.feishuSecret || '',
    intervalMinutes: Number(raw.intervalMinutes) || 15,
    stores: raw.stores || 'all',
    // 多店会话切店清单（店名与卖家中心顶栏英文名一致）。默认三店。
    storeList: Array.isArray(raw.storeList)
      ? raw.storeList
      : ['Agnis', 'HomeCove', 'Twilight Cove'],
    // 默认 true：赛狐下架 + 浏览器流量（对齐插件，无需 Chrome 扩展）
    fullRun: raw.fullRun !== false,
    alerts: {
      onSaleDrop: raw.alerts?.onSaleDrop !== false,
      trafficAnomaly: raw.alerts?.trafficAnomaly !== false,
      // 赛狐下架点名（fullRun 时启用）
      delist: raw.alerts?.delist !== false,
      // 登录过期/连续监测失败时发飞书提醒，避免登录态失效后静默死掉没人知道
      loginExpiry: raw.alerts?.loginExpiry !== false,
    },
    // 连续失败达到该轮次才发登录过期告警（默认 2 轮 ≈ 30 分钟，滤掉偶发抖动）
    loginAlertAfterRounds: Number(raw.loginAlertAfterRounds) || 2,
    // 仍未恢复时每隔多少轮再提醒一次（默认 16 轮 ≈ 4 小时，避免刷屏）
    loginRealertRounds: Number(raw.loginRealertRounds) || 16,
    headless: raw.headless === true,
    // 代理：config.proxy 若为字符串（含空串）则以它为准——空串 = 强制直连，
    // 不再回落系统 HTTPS_PROXY（实测本机 7897 代理会频繁 ERR_CONNECTION_CLOSED，直连反而稳）。
    // 仅当 config.json 完全没有 proxy 字段时才跟随系统环境变量。
    proxy: typeof raw.proxy === 'string' ? raw.proxy : (process.env.HTTPS_PROXY || process.env.HTTP_PROXY || ''),
    loginUrl: raw.loginUrl || 'https://agentseller.temu.com/goods/list',
    goodsListUrl: raw.goodsListUrl || 'https://agentseller.temu.com/goods/list',
    userDataDir: resolve(ROOT, raw.userDataDir || './.userdata'),
    // 浏览器 channel：默认 'chrome' = 用系统真实 Chrome（指纹与真人一致，最不易被风控识别）。
    // 设为 '' 或 'chromium' 则回落 Playwright 内置 Chromium。
    channel: raw.channel === '' ? '' : (raw.channel || 'chrome'),
    // 可选：显式指定 chrome.exe 路径，优先级高于 channel。
    executablePath: raw.executablePath || '',
    perStoreTimeoutMs: Number(raw.perStoreTimeoutMs) || 60000,
    navTimeoutMs: Number(raw.navTimeoutMs) || 60000,
  };
}

