1	/**
2	 * 开放平台快照 diff：下架 / 新进低流量 / 新进限流
3	 * 规则对齐插件：
4	 *  - 首轮只有基准不告警
5	 *  - 空扫 / 明显残缺不更新在售基准（防误报）
6	 */
7	
8	/**
9	 * @param {object} prev snapshot
10	 * @param {object} curr { activeMap, lowTrafficMap, restrictedMap, counts }
11	 * @param {object} alerts { delist, lowTraffic, restrictedTraffic }
12	 */
13	export function diffCatalog(prev, curr, alerts = {}) {
14	  const events = [];
15	  const prevActive = (prev && prev.activeMap) || null;
16	  const prevLow = (prev && prev.lowTrafficMap) || null;
17	  const prevRes = (prev && prev.restrictedMap) || null;
18	
19	  const currActive = curr.activeMap || {};
20	  const currLow = curr.lowTrafficMap || {};
21	  const currRes = curr.restrictedMap || {};
22	
23	  const activeIds = Object.keys(currActive);
24	  // 防残缺：若已有基准且本轮在售数 < 基准的 50% 且基准≥10，视为扫不全，跳过下架 diff 且不更新 active 基准
25	  let skipDelistUpdate = false;
26	  if (prevActive) {
27	    const prevN = Object.keys(prevActive).length;
28	    const currN = activeIds.length;
29	    if (prevN >= 10 && currN < Math.floor(prevN * 0.5)) {
30	      skipDelistUpdate = true;
31	      events.push({
32	        type: 'scan_incomplete',
33	        severity: 'warn',
34	        message: `在售扫描疑似不全：基准 ${prevN} → 本轮 ${currN}，跳过下架判定`,
35	      });
36	    }
37	  }
38	
39	  // —— 下架：上轮在售、本轮不在
40	  if (alerts.delist !== false && prevActive && !skipDelistUpdate) {
41	    const delisted = Object.keys(prevActive).filter((id) => !(id in currActive));
42	    if (delisted.length) {
43	      events.push({
44	        type: 'delist',
45	        severity: 'alert',
46	        items: delisted.map((id) => ({
47	          goodsId: id,
48	          name: prevActive[id]?.name || '',
49	        })),
50	        from: Object.keys(prevActive).length,
51	        to: activeIds.length,
52	      });
53	    }
54	  }
55	
56	  // —— 新进低流量
57	  if (alerts.lowTraffic !== false && prevLow) {
58	    const added = Object.keys(currLow).filter((id) => !(id in prevLow));
59	    if (added.length) {
60	      events.push({
61	        type: 'low_traffic',
62	        severity: 'alert',
63	        items: added.map((id) => ({
64	          goodsId: id,
65	          name: currLow[id]?.name || currActive[id]?.name || '',
66	        })),
67	        from: Object.keys(prevLow).length,
68	        to: Object.keys(currLow).length,
69	      });
70	    }
71	  }
72	
73	  // —— 新进限流
74	  if (alerts.restrictedTraffic !== false && prevRes) {
75	    const added = Object.keys(currRes).filter((id) => !(id in prevRes));
76	    if (added.length) {
77	      events.push({
78	        type: 'restricted_traffic',
79	        severity: 'alert',
80	        items: added.map((id) => ({
81	          goodsId: id,
82	          name: currRes[id]?.name || currActive[id]?.name || '',
83	        })),
84	        from: Object.keys(prevRes).length,
85	        to: Object.keys(currRes).length,
86	      });
87	    }
88	  }
89	
90	  const isFirst = !prevActive;
91	  const nextSnap = {
92	    activeMap: skipDelistUpdate && prevActive ? prevActive : currActive,
93	    lowTrafficMap: currLow,
94	    restrictedMap: currRes,
95	    counts: curr.counts || {
96	      active: activeIds.length,
97	      lowTraffic: Object.keys(currLow).length,
98	      restricted: Object.keys(currRes).length,
99	    },
100	    ts: Date.now(),
101	  };
102	
103	  return { events, nextSnap, isFirst, skipDelistUpdate };
104	}
105	
106	export function editLink(editBaseUrl, goodsId) {
107	  const base = String(editBaseUrl || 'https://agentseller.temu.com').replace(/\/$/, '');
108	  // 与插件一致：SPU/productId 编辑页；OpenAPI goodsId 需实测是否同一 ID
109	  return `${base}/goods/edit?from=productList&productId=${goodsId}`;
110	}
111	
112	export function formatAlertLines(storeName, events, { editBaseUrl } = {}) {
113	  const lines = [`**🏬 ${storeName}**（OpenAPI）`];
114	  for (const ev of events) {
115	    if (ev.severity !== 'alert') continue;
116	    if (ev.type === 'delist') {
117	      lines.push(`📉 在售商品下架 ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}）：`);
118	      for (const it of ev.items.slice(0, 30)) {
119	        const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
120	        lines.push(`• [${nm}](${editLink(editBaseUrl, it.goodsId)})  ID ${it.goodsId}`);

