228	// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
229	function nextWhen(hhmm) {
230	  const p = parseHHMM(hhmm);
231	  if (!p) return null;
232	  const now = new Date();
233	  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
234	  if (t.getTime() <= now.getTime() + 5000) t.setDate(t.getDate() + 1);
235	  return t.getTime();
236	}
237	function fmtNum(v) { return typeof v === 'number' ? String(v) : '—'; }
238	async function sendMustRemind(slot) {
239	  const cfg = await getConfig();
240	  if (!cfg.enabled || cfg.mustRemindEnabled === false) {
241	    log.info('MustRemind skipped: disabled');
242	    return { ok: false, msg: '未启用' };
243	  }
244	  if (!cfg.webhook) {
245	    log.warn('MustRemind skipped: no webhook');
246	    return { ok: false, msg: '未配置飞书 webhook' };
247	  }
248	  const stores = await getStores();
249	  const names = Object.keys(stores).sort();
250	  const lines = [
251	    '**定时必提醒' + (slot ? ' · ' + slot : '') + '**',
252	    '_插件存活汇报（无异常也会发）_',
253	    '',
254	  ];
255	  if (!names.length) {
256	    lines.push('_暂无店铺数据。请打开 goods/list 或点「轮巡所有店」。_');
257	  } else {
258	    for (const name of names) {
259	      const L = (stores[name] && stores[name].latest) || {};
260	      const stale = L.ts && (Date.now() - L.ts > 2 * 60 * 60 * 1000);
261	      lines.push('**🏬 ' + name + '**' + (stale ? ' ⚠️数据超过2小时未更新' : ''));
262	      lines.push(
263	        '在售 **' + fmtNum(L.onSale) + '**'
264	        + ' · 待关注 **' + fmtNum(L.trafficWatch) + '**'
265	        + ' · 下降 **' + fmtNum(L.trafficDecline) + '**'
266	        + ' · 总数 ' + fmtNum(L.total)
267	      );
268	      lines.push('上次检查：' + (L.ts ? new Date(L.ts).toLocaleString('zh-CN') : '—'));
269	      lines.push('');
270	    }
271	  }
272	  const lastCycle = (await chrome.storage.local.get('lastCycle')).lastCycle;
273	  if (lastCycle && lastCycle.ts) {
274	    lines.push('上次轮巡：' + new Date(lastCycle.ts).toLocaleString('zh-CN'));
275	  }
276	  lines.push('_汇报时间：' + new Date().toLocaleString('zh-CN') + '_');
277	  const r = await sendFeishu(cfg.webhook, '📋 Temu 监测定时汇报', lines, 'blue');
278	  await chrome.storage.local.set({ lastMustRemind: { ts: Date.now(), ok: r.ok, msg: r.msg, slot: slot || '' } });
279	  log.info('MustRemind done: slot=' + (slot || '') + ' ok=' + r.ok);
280	  return r;
281	}
282	async function setupMustRemindAlarms() {
283	  const all = await chrome.alarms.getAll();
284	  for (const a of all) {
285	    if (a.name.startsWith(MUST_REMIND_PREFIX)) await chrome.alarms.clear(a.name);
286	  }
287	  const cfg = await getConfig();
288	  if (cfg.mustRemindEnabled === false) {
289	    log.info('MustRemind alarms cleared (disabled)');
290	    return;
291	  }
292	  const raw = Array.isArray(cfg.mustRemindTimes) && cfg.mustRemindTimes.length
293	    ? cfg.mustRemindTimes
294	    : DEFAULT_CONFIG.mustRemindTimes;
295	  const seen = {};
296	  for (const t of raw) {
297	    const p = parseHHMM(t);
298	    if (!p || seen[p.label]) continue;
299	    seen[p.label] = true;
300	    const when = nextWhen(p.label);
301	    if (!when) continue;
302	    chrome.alarms.create(MUST_REMIND_PREFIX + p.label, { when });
303	    log.info('MustRemind alarm set: ' + p.label + ' → ' + new Date(when).toLocaleString('zh-CN'));
304	  }
305	}
