307	// ---------------- 商品明细 → 带链接的告警行 ----------------
308	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
309	function editLink(productId) {
310	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
311	}
312	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
313	function itemLines(items, total) {
314	  const lines = [];
315	  if (Array.isArray(items) && items.length) {
316	    for (const it of items) {
317	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
318	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
319	    }
320	    if (typeof total === 'number' && total > items.length) {
321	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
322	    }
323	  } else if (typeof total === 'number' && total > 0) {
324	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
325	  }
326	  return lines;
327	}
328	
329	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
330	async function scanWatchViaTab() {
331	  const tab = await getGoodsTab();
332	  if (!tab) return null;
333	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
334	}
335	
336	// ---------------- 对比 & 告警（按店） ----------------
337	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
338	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
339	const alertChains = {};
340	function diffAndAlert(name) {
341	  const prev = alertChains[name] || Promise.resolve();
342	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
343	  alertChains[name] = next;
344	  return next;
345	}
