347	async function _diffAndAlert(name) {
348	  const cfg = await getConfig();
349	  if (!cfg.enabled) return;
350	  const stores = await getStores();
351	  const s = stores[name];
352	  if (!s) return;
353	  const latest = s.latest || {};
354	  const snap = s.snapshot || {};
355	  const events = [];
356	
357	  // 在售数量下降：数字告警（被动监测第一时间发现），diffOnSale 在轮巡时带具体商品名+链接点名。
358	  // v3 曾移除此项（担心与 diffOnSale 重复），但 diffOnSale 只在空闲轮巡触发，移除后用户手动刷新/页面
359	  // 自然浏览时下架完全漏报——现在恢复，与 diffOnSale 互补：此处报数字，轮巡补点名。
360	  if (typeof latest.onSale === 'number' && typeof snap.onSale === 'number' && latest.onSale < snap.onSale) {
361	    events.push(`📉 在售数量下降：${snap.onSale} → ${latest.onSale}`);
362	  }
363	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
364	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
365	    // 被动扫到的 watchItems 往往为空（限流商品散落在其它页）→ 主动点筛选把这几条捞出来，带链接点名。
366	    let items = Array.isArray(latest.watchItems) ? latest.watchItems : [];
367	    let total = latest.trafficWatch;
368	    const scan = await scanWatchViaTab();
369	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
370	      items = scan.items;
371	      if (typeof scan.total === 'number') total = scan.total;
372	    }
373	    events.push(...itemLines(items, total));
374	  }
375	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
376	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
377	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
378	    events.push(...itemLines(latest.declineItems, null));
379	  }
380	
381	  if (events.length > 0) {
382	    log.info('Alert triggered: store=' + name + ' eventCount=' + events.length);
383	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
384	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
385	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
386	  }
387	
388	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次。
389	  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
390	  const stores2 = await getStores();
391	  const s2 = stores2[name] || s;
392	  const L2 = s2.latest || latest;
393	  const newSnap = Object.assign({}, s2.snapshot || snap);
394	  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
395	  if (typeof L2.total === 'number') newSnap.total = L2.total;
396	  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
397	  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
398	  newSnap.ts = Date.now();
399	  s2.snapshot = newSnap;
400	  stores2[name] = s2;
401	  await saveStores(stores2);
402	  log.info('Snapshot updated: store=' + name);
403	}
404	
405	// pageQuery 同商品 SKU 消失检测。
406	// 只对比「本轮 pageQuery 里再次出现的 productId」——当前页以外的商品本轮没看到，绝不判下架。
407	// 首轮只建 snapshot.productSkuMap，不告警。
408	async function diffProductSkus(name, products) {
409	  if (!Array.isArray(products) || !products.length) return 0;
410	  const cfg = await getConfig();
411	  const stores = await getStores();
412	  const s = stores[name] || { latest: {}, snapshot: {} };
413	  const prevMap = (s.snapshot && s.snapshot.productSkuMap) || {};
414	  const nextMap = Object.assign({}, prevMap);
415	  const removed = []; // { productId, productName, skc, skuId, name }
416	  let compared = 0;
417	
418	  for (const p of products) {
419	    if (!p || !p.productId) continue;
420	    const pid = String(p.productId);
421	    const currSkus = Array.isArray(p.skus) ? p.skus : [];
422	    // 当前商品在本页出现但 SKU 列表空：可能接口字段漂移/截断，跳过该商品、保留旧基准
423	    if (!currSkus.length) continue;
424	    const currById = {};
425	    for (const sk of currSkus) {
426	      if (sk && sk.skuId) currById[String(sk.skuId)] = sk;
427	    }
428	    const prev = prevMap[pid];
429	    if (prev && prev.skus && typeof prev.skus === 'object') {
430	      compared += 1;
431	      for (const skuId of Object.keys(prev.skus)) {
432	        if (!currById[skuId]) {
433	          const old = prev.skus[skuId] || {};
434	          removed.push({
435	            productId: pid,
436	            productName: p.name || prev.name || '',
437	            skc: p.skc || prev.skc || '',
438	            skuId,
439	            name: old.name || skuId,
440	          });
441	        }
442	      }
443	    }
444	    // 更新该 product 的 SKU 基准（只记 id→name）
445	    const skusObj = {};
446	    for (const sk of currSkus) {
447	      if (sk && sk.skuId) skusObj[String(sk.skuId)] = { name: sk.name || '', img: sk.img || '' };
448	    }
449	    nextMap[pid] = {
450	      name: p.name || (prev && prev.name) || '',
451	      skc: p.skc || (prev && prev.skc) || '',
452	      skus: skusObj,
453	      ts: Date.now(),
454	    };
455	  }
456	
457	  // 写回快照（合并式：本页商品更新，其它页旧基准保留）
458	  // 重新读 stores 避免覆盖并发写入
459	  const stores2 = await getStores();
460	  const s2 = stores2[name] || s;
461	  s2.snapshot = Object.assign({}, s2.snapshot || {}, { productSkuMap: nextMap });
462	  stores2[name] = s2;
463	  await saveStores(stores2);
464	
465	  if (!removed.length) {
466	    if (compared) log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=0');
467	    return 0;
468	  }
469	
470	  log.info('diffProductSkus: store=' + name + ' compared=' + compared + ' removed=' + removed.length);
471	  if (!cfg.enabled) return removed.length;
472	
473	  const lines = [
474	    '**🏬 ' + name + '**',
475	    '📦 后台检测到 SKU 规格消失 **' + removed.length + '** 个（同商品内对比，非整 SKC 下架）',
476	    '',
477	  ];
478	  // 按商品分组展示
479	  const byProduct = {};
480	  for (const r of removed) {
481	    const k = r.productId;
482	    if (!byProduct[k]) byProduct[k] = { productId: k, productName: r.productName, skc: r.skc, skus: [] };
483	    byProduct[k].skus.push(r);
484	  }
485	  for (const g of Object.values(byProduct)) {
486	    const nm = String(g.productName || '商品').replace(/[[\]]/g, '').slice(0, 30);
487	    lines.push('• [' + nm + '](' + editLink(g.productId) + ')' + (g.skc ? '  SKC ' + g.skc : ''));
488	    for (const sk of g.skus) {
489	      lines.push('   ❌ ' + (sk.name || sk.skuId) + '  (skuId ' + sk.skuId + ')');
490	    }
491	  }
492	  lines.push('');
493	  lines.push('_说明：对比来源 = 商品列表 pageQuery 的 productSkuSummaries；仅对「本页再次出现的商品」做 SKU 集合 diff，避免分页误报。_');
494	  lines.push('_检查时间：' + new Date().toLocaleString('zh-CN') + '_');
495	  const fr = await sendFeishu(cfg.webhook, '🔔 Temu SKU 规格消失', lines, 'orange');
496	  await chrome.storage.local.set({
497	    lastAlert: { ts: Date.now(), ok: fr.ok, msg: fr.msg, store: name, kind: 'skuRemoved', lines },
498	  });
499	  return removed.length;
500	}
501	
502	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
503	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
504	// scanStore 为扫描瞬间页面实际所在店：与 name 不符 = 切店竞态（这批是别店数据）→ 整轮作废。
505	async function diffOnSale(name, items, onSaleTabCount, scanStore) {
506	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
507	  if (scanStore && scanStore !== name) { log.warn('onSale scan store mismatch: want=' + name + ' got=' + scanStore + '，本轮作废'); return 0; }
508	  const cfg = await getConfig();
509	  const stores = await getStores();
510	  const s = stores[name] || { latest: {}, snapshot: {} };
511	  // 防残缺扫描/筛选污染误判：以"扫描当时在干净视图下读到的「在售中 N」"为权威在售数
512	  // （content.js scanOnSaleList 复位后读的，不会被「商品流量待关注」筛选污染）；
513	  // 读不到才回退 countStatus 的 latest.onSale。扫到的商品数必须恰好等于它：
514	  //   少了 = 没扫全/分页 → 跳过；多了 = 视图污染（全部/未发布/别店商品混入，可能含从未上架商品）→ 跳过。
515	  //   旧版只查"少"不查"多"，曾放过 20 条污染扫描（在售实为 13）写进基准，
516	  //   下一轮干净扫描引爆「下架15个(在售20→13)」假告警。
517	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount > 0)
518	    ? onSaleTabCount
519	    : (s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null);
520	  if (known != null && items.length < known) { log.warn('onSale scan incomplete: store=' + name + ' scanned=' + items.length + ' known=' + known); return 0; }
521	  if (known != null && items.length > known) { log.warn('onSale scan overflow: store=' + name + ' scanned=' + items.length + ' known=' + known + '，疑似视图污染，本轮作废'); return 0; }
522	  const newMap = {};
523	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
524	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
525	  let delistedCount = 0;
526	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
527	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
528	    delistedCount = delisted.length;
529	    if (delisted.length) {
530	      const added = Object.keys(newMap).filter((pid) => !(pid in prevMap)).length;
531	      log.warn('Delisted items: store=' + name + ' count=' + delisted.length + ' onSale=' + Object.keys(prevMap).length + '→' + items.length + ' added=' + added);
532	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
533	      // 「在售 A → B」的差值 ≠ 下架数（同期可能有新品上架）；补上新增数让账算得平：A - 下架 + 新增 = B
534	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}${added ? `，同期新增上架 ${added} 个` : ''}）:`,
535	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
536	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
537	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
538	    }
539	  } else {
540	    log.info('First onSale baseline: store=' + name + ' items=' + items.length);
541	  }
542	  // 重新取一次 stores 再写：_diffAndAlert 可能在 diffOnSale 处理期间并发更新过 snapshot 的
543	  // 数值字段（onSale/trafficWatch 等），直接用初始读到的 s 会覆盖掉这些更新 → 基准腐败 → "数据后来不准"。
544	  const stores2 = await getStores();
545	  const s2 = stores2[name] || s;
546	  s2.snapshot = Object.assign({}, s2.snapshot || s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
547	  stores2[name] = s2;
548	  await saveStores(stores2);
549	  return delistedCount;

